UPDATE fields x SET description = 'Plan 3: Treiber der TABLE9-Spalte für die sechs Anforderungswerte (*_tab9); Tab. 9 druckt die drei Spalten als eigene Rollen — der Naturteich-Typ (FLLNT-03) ist auf FLLNT-05 nicht vererbt und legt die Rolle nicht allein fest (Pflanzsubstrat in jedem Typ). Die Hälfte filter_iii / filter_iv wird NICHT gegen natural_pool_type plausibilisiert (nicht in Reichweite); eine spätere Ableitung braucht zuerst den Consumer-Edit FLLNT-03 → FLLNT-05 (Muster fll_naturteich-C-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'substrate_role';
UPDATE fields x SET description = 'Plan 3: Grenzwert aus TABLE9 zur gewählten Substratrolle (Filtersubstrat Typ III / Typ IV / Pflanzsubstrat; "no requirement" ⇒ leer); die gemessenen Werte filter_substrate_* / filter_grain_size_max / filter_kf bleiben Eingaben — Umbindung STAGED (fll_naturteich-E-1), Gate STAGED (fll_naturteich-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'grain_size_max_tab9';
UPDATE fields x SET description = 'Plan 3: Grenzwert aus TABLE9 zur gewählten Substratrolle (Filtersubstrat Typ III / Typ IV / Pflanzsubstrat; "no requirement" ⇒ leer); die gemessenen Werte filter_substrate_* / filter_grain_size_max / filter_kf bleiben Eingaben — Umbindung STAGED (fll_naturteich-E-1), Gate STAGED (fll_naturteich-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'oversize_max_tab9';
UPDATE fields x SET description = 'Plan 3: Grenzwert aus TABLE9 zur gewählten Substratrolle (Filtersubstrat Typ III / Typ IV / Pflanzsubstrat; "no requirement" ⇒ leer); die gemessenen Werte filter_substrate_* / filter_grain_size_max / filter_kf bleiben Eingaben — Umbindung STAGED (fll_naturteich-E-1), Gate STAGED (fll_naturteich-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'fines_max_tab9';
UPDATE fields x SET description = 'Plan 3: Grenzwert aus TABLE9 zur gewählten Substratrolle (Filtersubstrat Typ III / Typ IV / Pflanzsubstrat; "no requirement" ⇒ leer); die gemessenen Werte filter_substrate_* / filter_grain_size_max / filter_kf bleiben Eingaben — Umbindung STAGED (fll_naturteich-E-1), Gate STAGED (fll_naturteich-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'kf_min_tab9';
UPDATE fields x SET description = 'Plan 3: Grenzwert aus TABLE9 zur gewählten Substratrolle (Filtersubstrat Typ III / Typ IV / Pflanzsubstrat; "no requirement" ⇒ leer); die gemessenen Werte filter_substrate_* / filter_grain_size_max / filter_kf bleiben Eingaben — Umbindung STAGED (fll_naturteich-E-1), Gate STAGED (fll_naturteich-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'frost_resistance_tab9';
UPDATE fields x SET description = 'Plan 3: Grenzwert aus TABLE9 zur gewählten Substratrolle (Filtersubstrat Typ III / Typ IV / Pflanzsubstrat; "no requirement" ⇒ leer); die gemessenen Werte filter_substrate_* / filter_grain_size_max / filter_kf bleiben Eingaben — Umbindung STAGED (fll_naturteich-E-1), Gate STAGED (fll_naturteich-G-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.symbol = 'elutable_p_max_tab9';
UPDATE compliance_requirements x SET description = 'Concrete, wood, filter substrates, plant substrates, and granular materials meet §7.2 / Tab. 9.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.code = 'REQ-11';
UPDATE compliance_requirements x SET description = 'Filter substrate elutable phosphorus ≤ 5 mg P/kg per §7.2.3 + Tab. 9, tested via the Appendix 2 normative method (1 M HCl, 2:1 solid-solvent ratio, 24 h at 20±2 °C, per DIN 19529:2009-01).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-05' AND x.code = 'REQ-12';
UPDATE fields x SET description = 'Kurz gesagt: Beim Aushub ist der Untergrund tragfähig — andernfalls wurde er verdichtet oder anderweitig verbessert (z. B. geeignete Bodenschicht); falls erforderlich, wurde die Tragfähigkeit statisch nachgewiesen. (Kurzfassung EKOWAI, nicht normativ — maßgeblich FLL-Naturteich 2017 EN, §9.1 gedruckte S. 41)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'attest_fllnt_06_req_14';
UPDATE fields x SET description = 'Kurz gesagt: Der Schwimmbereich ist sicher und pflegbar gestaltet — keine scharfen Kanten, Oberflächen leicht zu reinigen, möglichst keine Pflanzen im Schwimmbereich; Bodenbeläge/Stufen trittsicher und rutschhemmend, Sand/Kies nur gewaschen; mindestens EIN Ein-/Ausstieg vorhanden, Metallleitern nach DIN VDE 0100-702 geerdet. (Kurzfassung EKOWAI, nicht normativ — maßgeblich FLL-Naturteich 2017 EN, §9.5.1–9.5.3 gedruckte S. 43)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'attest_fllnt_06_req_18';
UPDATE fields x SET description = 'Maximum water depth in the swimming area.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_depth_max';
UPDATE fields x SET description = 'Sum of pool bottom area + submerged wall area; drives the 50× filter colonized-surface rule.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_underwater_surface';
UPDATE fields x SET description = 'Surface area of the regeneration area.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'regeneration_area_m2';
UPDATE fields x SET description = 'Surface area of supplementary areas (e.g., decorative or auxiliary zones).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'supplementary_area_m2';
UPDATE fields x SET description = 'Surface area of the swimming area.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'swimming_area_m2';
UPDATE fields x SET description = 'Total water surface area, sum of zones.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'total_pool_area_m2';
UPDATE fields x SET description = 'Eingang zu pool_underwater_surface. App.5 Beispiel 2: Ground area 50 m².' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_ground_area_m2';
UPDATE fields x SET description = 'Eingang zu pool_underwater_surface. App.5 Beispiel 2: Wall area 45 m².' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_submerged_wall_area_m2';
UPDATE fields x SET description = 'Plan 3: Zeilen je Zone (Art, Fläche, Tiefe, Boden-/Wandfläche unter Wasser, Regenerationstechnik mit den prod-Token von regeneration_technique); Σ → total_pool_area_calc (FLLNT-06-D1), Regenerationsanteil an der Wasserfläche (Schwimm- + Regenerationsbereich, Tab. 2–6 "of the total water area") → regeneration_share_calc (FLLNT-06-D2), Σ Boden + Wand → pool_underwater_surface_calc (FLLNT-06-D3), submerser Anteil am Regenerationsbereich → submerged_hydrobot_share_calc (FLLNT-06-D4); Ablösung der Skalare swimming_area_m2 / regeneration_area_m2 / supplementary_area_m2 / total_pool_area_m2 und von EQ-PUWS STAGED (fll_naturteich-R-1 / -R-2); Ergänzungsflächen zählen nicht zur Wasserfläche (fll_naturteich-J-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'zonen';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung FLLNT-06-D1 (sum_rows über zonen) — entspricht der prod-Definition von total_pool_area_m2 ("sum of zones"); Übernahme STAGED (fll_naturteich-R-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'total_pool_area_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung FLLNT-06-D2; Vergleich mit regeneration_share_min_pct (FLLNT-03) und REQ-07-Umbindung STAGED (fll_naturteich-G-1); Ergänzungsflächen nicht im Nenner (fll_naturteich-J-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'regeneration_share_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung FLLNT-06-D3 (sum_rows über zonen.underwater_m2); Ablösung von EQ-PUWS (pool_underwater_surface = pool_ground_area_m2 + pool_submerged_wall_area_m2) STAGED (fll_naturteich-R-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'pool_underwater_surface_calc';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung FLLNT-06-D4 (Σ Regenerationszonen mit technique = hydrobotanical_submergent / Σ Regenerationszonen · 100); Vergleich mit TABLE2_SUBMERGED (50 %) für Typ I / II — Gate STAGED (fll_naturteich-G-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'submerged_hydrobot_share_calc';
UPDATE fields x SET description = 'Coverage block 3 (A-4/A-7): the reference quantity of the feed-rate rules ("% of the total water volume/day"); nothing in the encoding carried a volume before. Engineer input (the zones register carries areas and depths, not volumes).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.symbol = 'total_water_volume_m3';
UPDATE equations x SET description = 'Kolonisierbare Unterwasserfläche = Grundfläche + Unterwasser-Wandfläche.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'EQ-PUWS';
UPDATE equations x SET description = 'Plan 3: Σ Fläche über alle Zonen-Zeilen (Schwimm-, Regenerations- und Ergänzungsflächen — die prod-Definition von total_pool_area_m2 "sum of zones"); Übernahme als total_pool_area_m2 STAGED (fll_naturteich-R-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D1';
UPDATE equations x SET description = 'Plan 3: Regenerationsanteil an der Gesamtwasserfläche = Σ Regenerationszonen / Σ (Schwimm- + Regenerationszonen) · 100 (Tab. 2–6 "Regeneration area in % of the total water area"; Ergänzungsflächen gehören nicht zur Wasserfläche, §3 — fll_naturteich-J-4); Vergleich mit dem Tab.-1-Minimum (> 50 % / > 50 % / > 30 %) und REQ-07-Umbindung STAGED (fll_naturteich-G-1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D2';
UPDATE equations x SET description = 'Plan 3: Σ (Bodenfläche + Wandfläche unter Wasser) über die Zonen-Zeilen (App. 5 Beispiel 2: Ground area 50 m2 + Wall area 45 m2 = Total 95 m2); Ablösung von EQ-PUWS STAGED (fll_naturteich-R-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D3';
UPDATE equations x SET description = 'Plan 3: Anteil der Regenerationszonen mit submersem hydrobotanischem System an allen Regenerationszonen (Typ I / II: "therefrom at least half as submerged hydrobotanical system" — TABLE2_SUBMERGED 50 %); ohne Regenerationszeile unentscheidbar (Division durch Null); Gate STAGED (fll_naturteich-G-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.equation_number = 'FLLNT-06-D4';
UPDATE compliance_requirements x SET description = 'Swimming, regeneration, and supplementary areas sized per §8.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-13';
UPDATE compliance_requirements x SET description = 'Excavation per §9.1: subsoil load-bearing (or compacted/improved); drainage if groundwater or stratum water present; engineering rules ATV DIN 18300, DIN 1054, DIN 18196, DIN 4020, DIN 4124, DIN EN ISO 14688-1; excavation surface non-damaging to designated sealing material.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-14';
UPDATE compliance_requirements x SET description = 'Swimming area, ground coverings, entries and exits, walkways per §9.5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-18';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): "therefrom at least half" → ≥ 50 % of the regeneration area; submerged_hydrobot_share_calc (FLLNT-06-D4) already computes it, the comparison was STAGED and never live (A-9). Block (RULING as REQ-34).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-06' AND x.code = 'REQ-37';
UPDATE fields x SET description = 'Method by which the swimming and regeneration areas are separated.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'area_separation_method';
UPDATE fields x SET description = 'Edge / coping design type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'edge_design';
UPDATE fields x SET description = 'Maximum height deviation at the ends of the edges from the planned nominal height.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'edge_height_tolerance_mm';
UPDATE fields x SET description = 'Entry/exit, walkways, diving-board provisions.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'entry_exit_provision';
UPDATE fields x SET description = 'Excavation depth.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'excavation_depth';
UPDATE fields x SET description = 'Vertical distance from the consistent water level to the upper edge of the sealing system. Does not apply to technical equipment installed for water extraction.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'freeboard_water_to_seal';
UPDATE fields x SET description = 'Ground covering material in the swimming area.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'ground_covering_type';
UPDATE fields x SET description = 'Confirms that sealings and protective layers are not biocide-treated and that biofilm can form on the surface.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'sealing_biocide_free_biofilm_ok';
UPDATE fields x SET description = 'Method used to seal the pool basin (clay/loam, EPDM, PVC, concrete, other).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'sealing_type';
UPDATE fields x SET description = 'Coverage block 3 (A-38): on concrete the liner must be crease-free; without concrete the printed crease tolerances apply (REQ-38, staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'liner_on_concrete_base';
UPDATE fields x SET description = 'Coverage block 3 (A-38): "height of up to 1.0 cm" — REQ-38 (staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'crease_height_max_cm';
UPDATE fields x SET description = 'Coverage block 3 (A-38): "length of up to 2.0 m" — REQ-38 (staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'crease_length_max_m';
UPDATE fields x SET description = 'Coverage block 3 (A-38): "minimum distance of 2.0 m from each other" — REQ-38 (staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'crease_min_distance_m';
UPDATE fields x SET description = 'Coverage block 3 (A-38): "Creases are not permitted to cross over each other" — must be false (REQ-38, staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'creases_crossing';
UPDATE fields x SET description = 'Coverage block 3 (A-44): "at least one" — REQ-39 (staged); the free-text entry_exit_provision stays.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.symbol = 'entry_exit_point_count';
UPDATE compliance_requirements x SET description = 'Swimming area and regeneration area separated per §9.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-15';
UPDATE compliance_requirements x SET description = 'Basin sealing per §9.3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-16';
UPDATE compliance_requirements x SET description = 'Edge / coping designed per §9.4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-17';
UPDATE compliance_requirements x SET description = 'Edge design: water level ≥ 5 cm below upper edge of sealing system; sealing protected (e.g. mineral cover ≥ 8 mm grain or solid edging); capillary block prevents water discharge; edge permanently stable; surface water entry prevented; edge height tolerance ±10 mm.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-31';
UPDATE compliance_requirements x SET description = 'Sealings and protective layers are not biocide-treated; only sealings that allow surface biofilm formation are used (§9.3). Sealing system follows the FLL ''Empfehlungen für Abdichtungssysteme für Gewässer im Garten-, Landschafts- und Sportplatzbau''. Crease tolerances: ≤ 1.0 cm height, ≤ 2.0 m length, ≥ 2.0 m distance between, no crossings (synthetic/elastomer liners only). Stainless-steel pools earthed per VDE 0100-702.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-32';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): "can be tolerated" / "are not permitted" → block (RULING: on concrete the print demands crease-free — the gate accepts the concrete declaration as the crease-free case; a measured-creases-on-concrete state is not modelled).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-38';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): "There must be at least one" → block.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-07' AND x.code = 'REQ-39';
UPDATE fields x SET description = 'Register der Anlagenausstattung (§8.3): Element + Typ/Hersteller + Bemerkung. FLL-Quelle nicht in der Bibliothek — Auswahllisten nicht vorbelegt (Freitext, nicht erfunden).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-08' AND x.symbol = 'equipment_elements_list';
UPDATE fields x SET description = 'Confirms the works-contract service description is in place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-08' AND x.symbol = 'service_description_provided';
