UPDATE fields x SET description = 'Coverage block 3 (A-6): "maximum downtime 1 h" — REQ-36 (staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'filter_max_downtime_h';
UPDATE fields x SET description = 'Coverage block 3 (A-56 / B-1): the multiplier of the 150 l/m² rule is the inundated WATER SURFACE (plan area) of the connected area — single-area systems: the total water surface; multi-area: only the connected area. EQ-05 / REQ-33 currently multiply pool_underwater_surface (bottom + walls, App. 5) — wrong operand; the rewrite is 3b (staged).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.symbol = 'overflow_connected_water_surface_m2';
UPDATE equations x SET description = 'Überlaufkanten-Länge: 1 % der Schwimmbereichsfläche' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'EQ-04';
UPDATE equations x SET description = 'Schwallwasserbehälter-Volumen: ≥ 150 l/m² der überfluteten Wasserfläche — Coverage block 3b (2026-09-29): operand corrected to the inundated water surface of the connected area (§10.3.1); was pool_underwater_surface (bottom + walls).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'EQ-05';
UPDATE equations x SET description = 'Plan 3: Σ Überlaufkantenlänge über die Einrichtungen; der Richtwert "1% of the surface area of the swimming area in metres" bleibt EQ-04 (0.01 · swimming_area_m2), dessen Ausgabe heute das Eingabefeld overflow_edge_length ist — Umbenennung der Ausgabe und Gate Σ ≥ Richtwert STAGED (fll_naturteich-R-4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'FLLNT-11-D1';
UPDATE equations x SET description = 'Plan 3: Anzahl Überlaufkanten, deren horizontale Abweichung ±2 mm (bis 1 m Kantenlänge: ±1 mm) überschreitet; Zeilen ohne Messwert zählen nicht; Gate == 0 STAGED (fll_naturteich-G-7).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'FLLNT-11-D2';
UPDATE equations x SET description = 'Coverage block 3 (A-4/A-7): feed share of the total water volume per day; total_water_volume_m3 lives on FLLNT-06 (cross-sheet input, like pool_underwater_surface in EQ-01/EQ-03).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.equation_number = 'FLLNT-11-D3';
UPDATE compliance_requirements x SET description = 'If physical/chemical techniques are used, they are supplementary to biological methods (§10.2.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-24';
UPDATE compliance_requirements x SET description = 'None of the §10.1 impermissible treatments are used: disinfectants (chlorine, chlorine dioxide, ozone), biocides/biocidal products (insecticides, fungicides, algicides), heavy-metal-containing products, silver/copper-based techniques, UV disinfection, or sonification. These are categorical prohibitions, not ''supplementary-only'' allowances.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-29';
UPDATE compliance_requirements x SET description = 'Overflow edge length ≥ 1 % of swimming-area surface area (guide value per §10.3.1). Overflow edge horizontal tolerance ±2 mm (±1 mm for edges ≤ 1 m). Splash water tank (mandatory with rigid overflow weirs) provides ≥ 150 l/m² of inundated water surface.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-33';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): Table cell of the type definition ("< 10 h/day") → block (RULING: the type tables are definitions, not "must" sentences).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-34';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): Table cells ("> 25%", "> 80%") → block (RULING as REQ-34). Type V prints "filtration rate" where IV prints "filter feed rate" — read as the same quantity (RULING).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-35';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): Table cells → block (RULING as REQ-34).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-36';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): "are to be installed in a manner that" → block. overflow_tolerance_violations (FLLNT-11-D2) counts register rows over the printed tolerance; an empty register yields 0 (RULING whether ≥ 1 device row must exist). The scalar overflow_horizontal_tolerance_mm stays uncompared (legacy Plan-1 field).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-40';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): "As a guide … can be used" → warn. overflow_edge_length (EQ-04) is the required guide length (0.01 · swimming_area_m2); overflow_edge_length_total (FLLNT-11-D1) is the installed Σ over the register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-11' AND x.code = 'REQ-41';
UPDATE fields x SET description = 'Kurz gesagt: Die Bepflanzung ist typgerecht geplant — Pflanzen reinigen das Wasser (Nährstoffaufnahme, Besiedlungsfläche für den Biofilm; submers = unter Wasser, emers = Sumpfpflanzen); bei Typ I–III gelten wegen des nährstoffarmen Starts besonders hohe Anforderungen an Pflanzenauswahl, Saat-/Pflanzgutqualität und Substrat, und die Pflanzung selbst erfolgt sehr sorgfältig; Wurzeln dürfen die Filterfunktion nicht beeinträchtigen. (Kurzfassung EKOWAI, nicht normativ — maßgeblich FLL-Naturteich 2017 EN, §10.4 gedruckte S. 55–58 u. §6.2.2 S. 29)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'attest_fllnt_12_req_25';
UPDATE fields x SET description = 'Plant density for medium-height to tall marsh and aquatic plants.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_density_marsh_medium_per_m2';
UPDATE fields x SET description = 'Plant density for half-height to tall marsh and aquatic plants.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_density_marsh_small_per_m2';
UPDATE fields x SET description = 'Plant density for submerged plants, approximate value per m² of planting surface.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_density_submerged_per_m2';
UPDATE fields x SET description = 'Register der Pflanzenliste (§10.4): Pflanzenart + Zone/Beckentyp + Anzahl/Bemerkung. FLL-Quelle nicht in der Bibliothek — Listen nicht vorbelegt (Freitext, nicht erfunden).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_species_list';
UPDATE fields x SET description = 'Date planting was completed and the system is ready for acceptance inspection.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'planting_completion_date';
UPDATE fields x SET description = 'Confirms pre-maturity (establishment) plant care has been provided.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'pre_maturity_care_provided';
UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung FLLNT-12-D1 (sum_rows über plant_species_list.area_m2 · density); die drei Dichte-Skalare plant_density_* bleiben (fll_naturteich-X-2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.symbol = 'plant_count_total';
UPDATE equations x SET description = 'Plan 3: Σ Pflanzfläche · gewählte Dichte über die Pflanzenliste (Richtwerte je Gruppe aus S10_4_3: 6 – 10 / 3 – 5 / 5 – 7 je m², Seerosen nach Art; Topfware P 0.5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.equation_number = 'FLLNT-12-D1';
UPDATE compliance_requirements x SET description = 'Plants placed per §10.4; system ready for acceptance per §10.4.4; pre-maturity care provided per §10.4.5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-12' AND x.code = 'REQ-25';
UPDATE fields x SET description = 'Date of the acceptance inspection of the building work.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'acceptance_date';
UPDATE fields x SET description = 'Final acceptance verdict.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'acceptance_passed';
UPDATE fields x SET description = 'Kurz gesagt: Bei Kontrollen/Wartung festgestellte Reparaturen werden im vereinbarten Umfang ausgeführt — z. B. Filtermaterial ersetzen, defekte Technik tauschen, Pflanzen ersetzen/ergänzen, Einbauten instand setzen; nach einem unvermeidbaren Komplett-Wasserwechsel braucht das biologische System i. d. R. 1–2 Monate zur Stabilisierung. (Kurzfassung EKOWAI, nicht normativ — maßgeblich FLL-Naturteich 2017 EN, §12.4 gedruckte S. 64)' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'attest_fllnt_13_req_28';
UPDATE fields x SET description = 'Number of working days the supplier informs the purchaser before a completion date.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'completion_notice_days_advance';
UPDATE fields x SET description = 'Any defects recorded; basis for claims-due-to-defects (§11.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.symbol = 'defects_noted';
UPDATE compliance_requirements x SET description = 'Building work passed acceptance inspection per §11.1; defects (if any) recorded.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.code = 'REQ-26';
UPDATE compliance_requirements x SET description = 'Repair provisions in place; major water change accounts for 1–2 month re-stabilization (§12.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.code = 'REQ-28';
UPDATE compliance_requirements x SET description = 'Coverage block 3b (2026-09-29): "must inform … no later than 3 working days" → block. Field exists (required) but was never compared (A-66).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-13' AND x.code = 'REQ-42';
UPDATE fields x SET description = 'Frequency of checks and inspections.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.symbol = 'inspection_frequency';
UPDATE fields x SET description = 'Confirms a maintenance contract or schedule is in place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.symbol = 'maintenance_contract_in_place';
UPDATE fields x SET description = 'Provisions for repairs, including allowance for biological re-stabilization (1–2 months) after major water change.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.symbol = 'repair_provisions';
UPDATE compliance_requirements x SET description = 'Maintenance contract or schedule per §12.1–12.3 in place.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-14' AND x.code = 'REQ-27';
UPDATE fields x SET description = 'Pass/fail summary of Phase 1 worksheets (FLLNT-01, FLLNT-02).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_1_gate';
UPDATE fields x SET description = 'Pass/fail summary of Phase 2 worksheets (FLLNT-03, 04, 05).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_2_gate';
UPDATE fields x SET description = 'Pass/fail summary of Phase 3 worksheets (FLLNT-06, 07, 08).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_3_gate';
UPDATE fields x SET description = 'Pass/fail summary of Phase 4 worksheets (FLLNT-09, 10, 11).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_4_gate';
UPDATE fields x SET description = 'Pass/fail summary of Phase 5 (FLLNT-12).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_5_gate';
UPDATE fields x SET description = 'Pass/fail summary of Phase 6 worksheets (FLLNT-13, 14).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'phase_6_gate';
UPDATE fields x SET description = 'Aggregate engineering verdict over all phases.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-Naturteich' AND w.code = 'FLLNT-15' AND x.symbol = 'compliance_verdict_overall';
COMMIT;
